INSERT INTO `sk_training` (`title`, `title_en`, `cover_image`, `description`, `content`, `start_time`, `end_time`, `location`, `status`) VALUES
-- 培训1：半导体基础知识培训
('半导体基础知识培训', 'Semiconductor Basics Training', '/uploads/training/semiconductor-basics.jpg', '面向初学者的半导体基础知识培训，涵盖半导体物理、器件结构和制造工艺等内容。', '<h2>培训内容</h2><ul><li>半导体物理基础</li><li>二极管和晶体管工作原理</li><li>集成电路制造工艺</li><li>半导体材料特性</li></ul><h2>培训目标</h2><p>通过本培训，学员将掌握半导体的基本概念和工作原理，为后续深入学习打下坚实基础。</p>', '2026-01-15 09:00:00', '2026-01-15 17:00:00', '线上直播', 1),

-- 培训2：IC设计进阶课程
('IC设计进阶课程', 'Advanced IC Design Course', '/uploads/training/ic-design.jpg', '针对有经验的IC设计师，深入讲解先进工艺下的IC设计方法和工具使用。', '<h2>课程大纲</h2><ol><li>先进工艺下的设计挑战</li><li>低功耗设计技术</li><li>时序分析与优化</li><li>DFT设计方法</li><li>芯片验证技术</li></ol><h2>适合人群</h2><p>具有1-3年IC设计经验的工程师，希望提升在先进工艺下的设计能力。</p>', '2026-01-20 14:00:00', '2026-01-22 17:00:00', '上海张江高科技园区', 1),

-- 培训3：功率半导体应用研讨会
('功率半导体应用研讨会', 'Power Semiconductor Application Seminar', '/uploads/training/power-semiconductor.jpg', '探讨功率半导体在新能源、电动汽车等领域的应用和发展趋势。', '<h2>研讨主题</h2><ul><li>SiC和GaN功率器件的最新进展</li><li>电动汽车中的功率模块设计</li><li>新能源发电系统的功率转换</li><li>功率器件的可靠性设计</li></ul><h2>特邀嘉宾</h2><p>来自国内外知名企业的技术专家，分享最新的应用案例和技术见解。</p>', '2026-02-01 09:00:00', '2026-02-01 16:30:00', '深圳南山科技园', 1),

-- 培训4：半导体测试技术培训
('半导体测试技术培训', 'Semiconductor Testing Technology Training', '/uploads/training/semiconductor-testing.jpg', '全面介绍半导体测试的原理、方法和设备，提升测试工程师的专业技能。', '<h2>培训模块</h2><ol><li>半导体测试基础</li><li>ATE测试系统介绍</li><li>晶圆测试和成品测试</li><li>测试程序开发</li><li>测试数据分析与良率提升</li></ol><h2>实践环节</h2><p>提供实际测试设备的操作演练，让学员掌握测试流程和故障分析方法。</p>', '2026-02-10 09:00:00', '2026-02-12 17:00:00', '北京亦庄经济技术开发区', 1),

-- 培训5：摩尔定律与后摩尔时代
('摩尔定律与后摩尔时代', 'Moore\'s Law and Post-Moore Era', '/uploads/training/moores-law.jpg', '深入分析摩尔定律的发展历程和挑战，探讨后摩尔时代的技术路径和创新方向。', '<h2>演讲内容</h2><ul><li>摩尔定律的历史与现状</li><li>延续摩尔定律的技术挑战</li><li>后摩尔时代的技术路线图</li><li>新型计算架构的发展</li><li>量子计算与类脑计算</li></ul><h2>互动环节</h2><p>设置专家对话和现场提问环节，与行业领袖深入探讨未来发展趋势。</p>', '2026-02-20 14:30:00', '2026-02-20 17:30:00', '线上直播+线下分会场', 1),

-- 培训6：半导体封装与测试技术
('半导体封装与测试技术', 'Semiconductor Packaging and Testing Technology', '/uploads/training/packaging-testing.jpg', '介绍先进的半导体封装技术和测试方法，包括晶圆级封装、系统级封装等。', '<h2>培训内容</h2><ul><li>传统封装与先进封装技术对比</li><li>晶圆级封装(WLP)技术</li><li>系统级封装(SiP)设计</li><li>先进封装的可靠性测试</li><li>封装材料与工艺</li></ul><h2>案例分析</h2><p>通过实际产品案例，讲解先进封装技术在不同领域的应用。</p>', '2026-03-01 09:00:00', '2026-03-03 17:00:00', '苏州工业园区', 1),

-- 培训7：半导体材料与工艺技术
('半导体材料与工艺技术', 'Semiconductor Materials and Process Technology', '/uploads/training/materials-process.jpg', '全面讲解半导体材料的特性和制造工艺，包括晶体生长、光刻、刻蚀等关键工艺。', '<h2>课程模块</h2><ol><li>半导体材料基础</li><li>晶体生长技术</li><li>光刻工艺与设备</li><li>刻蚀与沉积技术</li><li>掺杂与离子注入</li><li>薄膜生长技术</li></ol><h2>参观环节</h2><p>安排参观先进的半导体制造工厂，实地了解生产流程和设备。</p>', '2026-03-10 09:00:00', '2026-03-14 17:00:00', '无锡高新区', 1),

-- 培训8：半导体知识产权保护
('半导体知识产权保护', 'Semiconductor Intellectual Property Protection', '/uploads/training/ip-protection.jpg', '讲解半导体行业的知识产权保护策略，包括专利申请、侵权风险防范等内容。', '<h2>培训要点</h2><ul><li>半导体行业知识产权现状</li><li>专利申请策略与技巧</li><li>IP侵权风险识别与防范</li><li>专利许可与合作模式</li><li>国际知识产权保护体系</li></ul><h2>专家团队</h2><p>邀请资深知识产权律师和行业专家，分享实际案例和经验。</p>', '2026-03-20 14:00:00', '2026-03-20 17:30:00', '线上直播', 1);
